from rich.console import Console
import sys

def recurse(n):
    return recurse(n + 1)

console = Console()

try:
    recurse(1)
except RecursionError:
    try:
        console.print_exception()
    except RecursionError:
        print("Caught recursion error in console.print_exception!")
