from rich.traceback import install

def recursive_function():
    return recursive_function()

def test_recursion():
    try:
        recursive_function()
    except RecursionError:
        # This should be handled by rich.traceback if installed
        # But we are testing if the printing itself crashes
        print("Caught RecursionError, now letting rich handle it...")
        raise

if __name__ == "__main__":
    install()
    try:
        test_recursion()
    except Exception:
        # If we get here, the rich handler likely finished
        pass

